it('sums each token field only for provider rounds that report usage, preserving undefined when none do', async () => {
  let seenWithGaps: TotalUsage | undefined;
  let seenWithoutUsage: TotalUsage | undefined = {inputTokens: 99, outputTokens: 99, totalTokens: 99};

  const orchestratorWithGaps = createChatOrchestrator(
    scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
      [TOOL_CALL, STOP_FOR_TOOL],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 3, totalTokens: 23}},
      ],
    ]),
    promptBuilder,
    registryReturning({result: 'r'}),
    {
      hooks: {
        afterModelResponse: async (_session, _text, totalUsage) => {
          seenWithGaps = totalUsage;
        },
      },
    }
  );

  const orchestratorWithoutUsage = createChatOrchestrator(
    scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'done'}, STOP_DONE],
    ]),
    promptBuilder,
    registryReturning({result: 'r'}),
    {
      hooks: {
        afterModelResponse: async (_session, _text, totalUsage) => {
          seenWithoutUsage = totalUsage;
        },
      },
    }
  );

  await orchestratorWithGaps.processMessage(createSession('ask'));
  await orchestratorWithoutUsage.processMessage(createSession('ask'));

  expect(seenWithGaps).toEqual({inputTokens: 30, outputTokens: 5, totalTokens: 35});
  expect(seenWithoutUsage).toBeUndefined();
});

